/**
 * Checks whether a story should be hidden because its title contains one of the user's
 * filtered words, or because its url contains one of the user's filtered domains.
 */
private boolean shouldFilterStory(Story story) {
    if (story == null) {
        return false;
    }

    if (!TextUtils.isEmpty(story.title) && filterWords != null) {
        String lowerCaseTitle = story.title.toLowerCase();
        for (String phrase : filterWords) {
            if (!TextUtils.isEmpty(phrase) && lowerCaseTitle.contains(phrase.toLowerCase())) {
                return true;
            }
        }
    }

    if (!TextUtils.isEmpty(story.url) && filterDomains != null) {
        String lowerCaseUrl = story.url.toLowerCase();
        for (String phrase : filterDomains) {
            if (!TextUtils.isEmpty(phrase) && lowerCaseUrl.contains(phrase.toLowerCase())) {
                return true;
            }
        }
    }

    return false;
}

